import img_ranking from '@/assets/images/img_ranking@2x.png'
import LaunchTable from '@/components/ranking/LaunchTable'
import MarketCapTable from '@/components/ranking/MarketCapTable'
import PriceIncreaseTable from '@/components/ranking/PriceIncreaseTable'
import TradingTable from '@/components/ranking/TradingTable'
import { usePumpTokenList } from '@/hook/pump'
import { PumpToken, PumpTokenListQuery } from '@/type/pump'
import { Block } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Flex, HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

export default function RankingPage() {
  const { fetchPumpTokenList, isLoadMoreError } = usePumpTokenList()
  const baseQuery = {
    page: 1,
    page_size: 10,
    if_asc: false
  }
  const [launchTableList, setLaunchTableList] = useState<PumpToken[]>([])
  const [marketCapTableList, setMarketCapTableList] = useState<PumpToken[]>([])
  const [priceIncreaseTableList, setPriceIncreaseTableList] = useState<PumpToken[]>([])
  const [tradingTableList, setTradingTableList] = useState<PumpToken[]>([])
  const [loading, setLoading] = useState<boolean>(true)
  const [launchParams, setLaunchParams] = useState({ loading: false, isError: false })
  const [marketParams, setMarketParams] = useState({ loading: false, isError: false })

  const [priceParams, setPriceParams] = useState({ loading: false, isError: false })

  const [tradeParams, setTradeParams] = useState({ loading: false, isError: false })

  const fetchLaunchData = async () => {
    const launchQuery: PumpTokenListQuery = { ...baseQuery, order_by_type: 'launch' }
    try {
      setLaunchParams(pre => ({ ...pre, loading: true, isError: false }))
      const launchList: PumpToken[] | undefined = await fetchPumpTokenList({ ...launchQuery, if_on_dex: false }, true)
      console.log('🚀 ~ useEffect ~ launchList:', launchList)
      setLaunchTableList(launchList)
    } catch (error) {
      console.error('Error fetching pump token list:', error)
      setLaunchParams(pre => ({ ...pre, isError: true }))
    } finally {
      setLaunchParams(pre => ({ ...pre, loading: false }))
    }
  }
  const fetchMarketData = async () => {
    const marketCapQuery: PumpTokenListQuery = { ...baseQuery, order_by_type: 'marketcap' }
    try {
      setMarketParams(pre => ({ ...pre, loading: true, isError: false }))
      const marketList: PumpToken[] | undefined = await fetchPumpTokenList(marketCapQuery, true)
      console.log('🚀 ~ useEffect ~ marketList:', isLoadMoreError, marketList)
      setMarketCapTableList(marketList)
    } catch (error) {
      console.error('Error fetching pump token list:', error)
      setMarketParams(pre => ({ ...pre, isError: true }))
    } finally {
      setMarketParams(pre => ({ ...pre, loading: false }))
    }
  }
  const fetchPriceData = async () => {
    const priceIncreaseQuery: PumpTokenListQuery = { ...baseQuery, order_by_type: 'price24h' }
    try {
      setPriceParams(pre => ({ ...pre, loading: true, isError: false }))
      const priceList: PumpToken[] | undefined = await fetchPumpTokenList(priceIncreaseQuery, true)
      console.log('🚀 ~ useEffect ~ priceList:', priceList)
      setPriceIncreaseTableList(priceList)
    } catch (error) {
      console.error('Error fetching pump token list:', error)
      setPriceParams(pre => ({ ...pre, isError: true }))
    } finally {
      setPriceParams(pre => ({ ...pre, loading: false }))
    }
  }
  const fetchTradingData = async () => {
    const tradingVolumeQuery: PumpTokenListQuery = { ...baseQuery, order_by_type: 'volume24h' }
    try {
      setTradeParams(pre => ({ ...pre, loading: true, isError: false }))
      const tradeList: PumpToken[] | undefined = await fetchPumpTokenList(tradingVolumeQuery, true)
      console.log('🚀 ~ useEffect ~ tradeList:', tradeList)
      setTradingTableList(tradeList)
    } catch (error) {
      console.error('Error fetching pump token list:', error)
      setTradeParams(pre => ({ ...pre, isError: true }))
    } finally {
      setTradeParams(pre => ({ ...pre, loading: false }))
    }
  }

  const fetchData = async () => {
    try {
      await fetchLaunchData()
      await fetchMarketData()
      await fetchPriceData()
      await fetchTradingData()
    } catch (error) {
      console.error('Error fetching pump token list:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchData()
  }, [])

  const { isApp } = useWindowWidth()
  const [currentTable, setCurrentTable] = useState('launch')
  const tableList = [
    {
      label: 'Launching soon',
      value: 'launch'
    },
    {
      label: 'Market Cap Ranking',
      value: 'marketcap'
    },
    {
      label: '24H Price Increase in bonding Curve',
      value: 'price24h'
    },
    {
      label: '24H Trading Vol(SUI)',
      value: 'volume24h'
    }
  ]
  return (
    <VStack w="100%" position="relative" mt={{ base: '0', lg: '52px' }} gap="20px">
      <Flex
        align="center"
        justifyContent="center"
        w={{
          base: '100%',
          lg: '616px'
        }}
        h="118px"
        minH="118px"
        bgImage={img_ranking}
        backgroundRepeat="no-repeat"
        backgroundPosition="center"
        backgroundSize="contain"
      >
        <Text
          textAlign="center"
          fontSize={{
            base: '24px',
            lg: '40px'
          }}
          color="text_caption"
          fontWeight="bold"
        >
          Cetus Pump Ranking
        </Text>
      </Flex>
      {isApp && (
        <Block w="100%" p="4px" borderRadius="8px">
          <VStack w="100%" gap="4px">
            {tableList.map(item => {
              return (
                <Text
                  borderRadius="4px"
                  w="100%"
                  h="32px"
                  lineHeight="32px"
                  textAlign="center"
                  fontSize="14px"
                  bg={currentTable == item.value ? 'primary_opacity.10' : ''}
                  color={currentTable == item.value ? 'primary' : 'primary_gray'}
                  key={item.value}
                  onClick={() => setCurrentTable(item.value)}
                >
                  {item?.label}
                </Text>
              )
            })}
          </VStack>
        </Block>
      )}
      <HStack
        w="100%"
        gap={{ lg: '10px', xl: '20px' }}
        align="flex-start"
        flexWrap="wrap"
        borderRadius="20px"
        border="1px solid"
        borderColor={{ base: 'border', lg: 'transparent' }}
        bg={{ base: 'bg_secondary', lg: 'transparent' }}
      >
        {(!isApp || (isApp && currentTable == 'launch')) && (
          <LaunchTable list={launchTableList} loading={loading || launchParams.loading} isError={launchParams.isError} onRefresh={fetchLaunchData} />
        )}
        {(!isApp || (isApp && currentTable == 'marketcap')) && (
          <MarketCapTable
            list={marketCapTableList}
            loading={loading || marketParams.loading}
            isError={marketParams.isError}
            onRefresh={fetchMarketData}
          />
        )}
        {(!isApp || (isApp && currentTable == 'price24h')) && (
          <PriceIncreaseTable
            list={priceIncreaseTableList}
            loading={loading || priceParams.loading}
            isError={priceParams.isError}
            onRefresh={fetchPriceData}
          />
        )}
        {(!isApp || (isApp && currentTable == 'volume24h')) && (
          <TradingTable list={tradingTableList} loading={loading || tradeParams.loading} isError={tradeParams.isError} onRefresh={fetchTradingData} />
        )}
      </HStack>
    </VStack>
  )
}
