import { PumpToken, PumpTokenDetail } from '@/type/pump'
import { Block } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { NoData, Table } from '@cetus/ui-kit'
import H5MapTable from '@cetus/ui-kit/src/components/H5MapTable'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'
import FetchError from '../common/FetchError'
import MarketCapBlock from '../common/MarketCapBlock'
import SingleToken from '../common/SingleToken'
import RankingImg from './RankingImg'
import { TableProps } from './type'
const getColumns = (loading: boolean) => {
  return [
    {
      title: (
        <Text
          fontSize="14px"
          pl={{
            base: 0,
            lg: loading ? '0' : '36px !important'
          }}
        >
          Name (Symbol)
        </Text>
      ),
      hiddenTitle: true,
      key: 'name',
      tdConfig: {
        h: '60px',
        cursor: 'pointer'
      },
      render: ({ TokenDetail }: { TokenDetail: PumpTokenDetail }, index: number) => {
        return (
          <HStack
            justifyContent={{
              base: 'flex-end',
              lg: 'flex-start'
            }}
            align="center"
            pl="32px !important"
          >
            <RankingImg index={index} />
            <SingleToken
              token={TokenDetail}
              w={{
                base: 'unset',
                lg: '200px'
              }}
            />
          </HStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Market Cap</Text>,
      key: 'market_cap',
      render: (item: PumpToken) => {
        return <MarketCapBlock pumpToken={item} justifyContent="flex-end" />
      }
    }
  ]
}
function MarketCapTable({ list, loading, isError, onRefresh }: TableProps) {
  const navigate = useNavigate()
  const { isApp } = useWindowWidth()
  return (
    <VStack
      w={isApp ? '100%' : 'calc(50% - 10px)'}
      position="relative"
      mt={{ base: '12px', lg: '35px' }}
      gap="20px"
      p={{ base: '8px', lg: 0 }}
      background={{ base: 'ranking_list_h5_bg', lg: 'transparent' }}
    >
      <HStack
        w="100%"
        align={{ base: 'flex-start', xl: 'center' }}
        justifyContent={{ base: 'flex-start', xl: 'space-between' }}
        flexDirection={{ base: 'column', xl: 'row' }}
      >
        <Text fontSize="20px" color="launch_title" fontWeight="500">
          Market Cap Ranking
        </Text>
        <Text fontSize="14px" color="transparent" display={{ base: 'none', lg: 'block' }}>
          Progress reaches 100%, token deploys on Cetus DEX
        </Text>
      </HStack>
      {isError ? (
        <FetchError onClick={onRefresh} minH={{ base: 'unset', lg: '650px' }} borderRadius="20px" />
      ) : !loading && list?.length == 0 ? (
        <NoData type="nodata" minH={{ base: 'unset', lg: '650px' }} borderRadius="20px" />
      ) : isApp ? (
        <H5MapTable<PumpToken>
          dataSource={list}
          columns={getColumns(loading)}
          loading={loading}
          rowKey="coin_type"
          itemSkeletonLength={2}
          rowStyle={{
            w: '100%',
            p: '8px',
            bg: 'bg_secondary',
            border: '1px solid',
            borderColor: 'border',
            borderRadius: '20px'
          }}
          onRowClick={item => {
            navigate(`/trade/${item?.coin_type}`)
          }}
        />
      ) : (
        <Block p="0" pt="24px" bg="market_table_bg" overflow="hidden">
          <Table<PumpToken>
            rowKey="coin_type"
            columns={getColumns(loading)}
            dataSource={list}
            skeletonLength={10}
            loading={loading}
            onRowClick={item => {
              navigate(`/trade/${item?.coin_type}`)
            }}
            rowStyle={{ h: '60px', cursor: 'pointer' }}
          />
        </Block>
      )}
    </VStack>
  )
}

export default MarketCapTable
