import { usePumpTokenHelper } from '@/hook/pump/usePumpTokenHelper'
import { PumpToken } from '@/type/pump'
import { formatPercentage } from '@cetus/utils'
import { HStack, Progress, Text } from '@chakra-ui/react'

export default function BondingCurveBlock({ pumpToken }: { pumpToken: PumpToken }) {
  const { raising_progress } = usePumpTokenHelper(pumpToken)
  return (
    <HStack align="center" justifyContent="flex-end">
      <Text color="text_caption" fontWeight="500">
        {formatPercentage(raising_progress)}
      </Text>
      <Progress h="4px" value={Number(raising_progress)} w="72px" />
    </HStack>
  )
}
